print(f"Data span: {real_hours[-1]/24:.1f} days, {len(real_hours)} hourly points")

# ---------- Model A: original REPRESENTATIVE (guessed) constituents ----------
def predict_representative(t):
    mean = 8.0
    m2 = 6.0 * np.cos(2*np.pi/12.42 * t - 0.0)
    s2 = 1.3 * np.cos(2*np.pi/12.00 * t - 0.6)
    n2 = 1.2 * np.cos(2*np.pi/12.66 * t - 1.1)
    return mean + m2 + s2 + n2

pred_A = predict_representative(real_hours)
rmse_A = np.sqrt(np.mean((pred_A - real_levels)**2))
mae_A = np.mean(np.abs(pred_A - real_levels))

# ---------- Model B: FIT M2/S2/N2 to the real 30-day data via least squares ----------
periods = {"M2": 12.42, "S2": 12.00, "N2": 12.66}
cols = [np.ones_like(real_hours, dtype=float)]
for name, p in periods.items():
    w = 2*np.pi/p
    cols.append(np.cos(w*real_hours))
    cols.append(np.sin(w*real_hours))
X = np.column_stack(cols)

coeffs, *_ = np.linalg.lstsq(X, real_levels, rcond=None)
mean_fit = coeffs[0]
fitted = {}
idx = 1
for name, p in periods.items():
    a, b = coeffs[idx], coeffs[idx+1]
    amplitude = np.sqrt(a**2 + b**2)
    phase = np.arctan2(b, a)  # matches cos(wt - phase) convention used in tide-model.js
    fitted[name] = (amplitude, phase, p)
    idx += 2

pred_B = X @ coeffs
rmse_B = np.sqrt(np.mean((pred_B - real_levels)**2))
mae_B = np.mean(np.abs(pred_B - real_levels))

print("\n=== REPRESENTATIVE (original guess) model ===")
print(f"RMSE: {rmse_A:.3f} m   MAE: {mae_A:.3f} m")
print("\n=== FITTED (least-squares against real 30-day Burntcoat Head data) ===")
print(f"Mean sea level: {mean_fit:.3f} m")
for name, (amp, phase, p) in fitted.items():
    print(f"  {name}: amplitude={amp:.3f} m, phase={phase:.3f} rad, period={p} h")
print(f"RMSE: {rmse_B:.3f} m   MAE: {mae_B:.3f} m")
print(f"\nImprovement: RMSE reduced by {(1 - rmse_B/rmse_A)*100:.1f}%")
